-- M1 第四块 PR1：知识库、知识库文件；kb_chunks（手写，不进 ent：pgvector / tsvector 列与 HNSW 索引）。
-- Create "kb_files" table
CREATE TABLE "kb_files" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "org_id" bigint NOT NULL, "kb_id" bigint NOT NULL, "name" character varying NOT NULL, "kind" character varying NOT NULL, "size" bigint NOT NULL, "sha256" character varying NOT NULL, "object_key" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'pending', "error_code" character varying NOT NULL DEFAULT '', "error" character varying NOT NULL DEFAULT '', "chars" bigint NOT NULL DEFAULT 0, "chunk_count" bigint NOT NULL DEFAULT 0, "acl_custom" boolean NOT NULL DEFAULT false, "uploaded_by" bigint NOT NULL, "embedding_model" character varying NOT NULL DEFAULT '', "attempts" bigint NOT NULL DEFAULT 0, "indexed_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "kbfile_kb_id_name" to table: "kb_files"
CREATE UNIQUE INDEX "kbfile_kb_id_name" ON "kb_files" ("kb_id", "name");
-- Create index "kbfile_kb_id_sha256" to table: "kb_files"
CREATE UNIQUE INDEX "kbfile_kb_id_sha256" ON "kb_files" ("kb_id", "sha256");
-- Create index "kbfile_org_id_status" to table: "kb_files"
CREATE INDEX "kbfile_org_id_status" ON "kb_files" ("org_id", "status");
-- Create "knowledge_bases" table
CREATE TABLE "knowledge_bases" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "org_id" bigint NOT NULL, "name" character varying NOT NULL, "description" character varying NOT NULL DEFAULT '', "embedding_model" character varying NOT NULL, "chunk_size" bigint NOT NULL DEFAULT 800, "chunk_overlap" bigint NOT NULL DEFAULT 100, "created_by" bigint NOT NULL, "deleted_at" timestamptz NULL, PRIMARY KEY ("id"));
-- Create index "knowledgebase_org_id_deleted_at" to table: "knowledge_bases"
CREATE INDEX "knowledgebase_org_id_deleted_at" ON "knowledge_bases" ("org_id", "deleted_at");
-- kb_chunks：知识库切片。embedding 固定 1024 维（docs/progress/m1-block4.md 待确认第 1 条）；
-- tsv 由 Go 侧 gse 分词后以 simple 配置写入。ACL 不落在 chunk 上：检索时按 file_id = ANY(allowed) 预过滤（D-14 / D-27）。
CREATE TABLE "kb_chunks" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "org_id" bigint NOT NULL, "kb_id" bigint NOT NULL, "file_id" bigint NOT NULL, "seq" integer NOT NULL, "content" text NOT NULL, "heading" text NOT NULL DEFAULT '', "char_start" integer NOT NULL DEFAULT 0, "char_end" integer NOT NULL DEFAULT 0, "embedding" vector(1024) NOT NULL, "tsv" tsvector NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX "kbchunk_file_id_seq" ON "kb_chunks" ("file_id", "seq");
CREATE INDEX "kbchunk_kb_id" ON "kb_chunks" ("kb_id");
CREATE INDEX "kbchunk_tsv" ON "kb_chunks" USING gin ("tsv");
CREATE INDEX "kbchunk_embedding_hnsw" ON "kb_chunks" USING hnsw ("embedding" vector_cosine_ops) WITH (m = 16, ef_construction = 64);
